    "main.jsx": "import React, { useState } from 'react';
import ReactDOM from 'react-dom/client';

function Counter() {
  const [n, setN] = useState(0);
  return (<div style={{padding: '2rem', fontFamily: 'system-ui'}}>
    <h1>count: {n}</h1>
    <button onClick={() => setN(n + 1)}>+</button>
    <button onClick={() => setN(0)}>reset</button>
  </div>);
}

ReactDOM.createRoot(document.getElementById('root')).render(<Counter />);
",
    "tests/counter.test.js": "const { chromium } = require('playwright');

test('counter increments on click', async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto(process.env.PREVIEW_URL);
  await expect(page.getByRole('heading', { name: /count: 0/ })).toBeVisible({ timeout: 15000 });
  await page.getByRole('button', { name: '+' }).click();
  await expect(page.getByRole('heading', { name: /count: 1/ })).toBeVisible();
  await browser.close();
}, 30000);
